style.css:
@-moz-document domain("discord.com") {
/* Main app background */
  .bg_e872e1, 
  [class*="bg_"] {
    background-image: url("https://i.imgur.com/TTAicUa.gif") !important;
    background-size: cover !important;
    background-position: center !important;
  }

  /* Make chat area background transparent so the gif shows through */
  [class*="chatContent_"],
  [class*="content_"] {
    background-color: transparent !important;
  }
}
